<?php
require_once __DIR__.'/../includes/admin-functions.php';$schema=dental_schema($pdo);$sid=$schema->serviceId();$sname=$schema->serviceName();$error='';$flash=admin_take_flash();$editId=(int)($_GET['id']??0);$editing=null;
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);$name=trim((string)($_POST['nom']??''));try{if($action==='delete'){$pdo->prepare("DELETE FROM service WHERE `$sid`=?")->execute([$id]);admin_flash('success','Service supprimé avec ses associations.');admin_redirect('services.php');}if($action!=='save'||$name===''||mb_strlen($name)>100)throw new RuntimeException('Le nom du service est obligatoire (100 caractères maximum).');if($id){$pdo->prepare("UPDATE service SET `$sname`=? WHERE `$sid`=?")->execute([$name,$id]);}else{$pdo->prepare("INSERT INTO service(`$sname`) VALUES(?)")->execute([$name]);}admin_flash('success','Service enregistré.');admin_redirect('services.php');}catch(PDOException $e){$error='Ce service existe déjà ou la base de données a refusé la modification.';}catch(RuntimeException $e){$error=$e->getMessage();}}
if($editId){$q=$pdo->prepare("SELECT `$sid` id,`$sname` nom FROM service WHERE `$sid`=?");$q->execute([$editId]);$editing=$q->fetch();}$search=trim((string)($_GET['q']??''));$params=[];$where='';if($search!==''){$where="WHERE s.`$sname` LIKE ?";$params[]='%'.$search.'%';}$q=$pdo->prepare("SELECT s.`$sid` id,s.`$sname` nom,COUNT(ls.laboratoire_id) lab_count FROM service s LEFT JOIN laboratoire_service ls ON ls.service_id=s.`$sid` $where GROUP BY s.`$sid`,s.`$sname` ORDER BY s.`$sname`");$q->execute($params);$services=$q->fetchAll();
$pageTitle='Services dentaires';$assetPrefix='../';$navContext='admin';$pageStyles=['assets/css/admin.css'];$pageScripts=['assets/js/admin.js'];require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';
?>
<main class="admin-main"><div class="admin-heading"><div><p class="admin-eyebrow">Catalogue partagé</p><h1>Services dentaires</h1></div></div><?php if($flash):?><div class="admin-alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?><?php if($error):?><div class="admin-alert error" role="alert"><?=e($error)?></div><?php endif;?><section class="admin-panels services-layout"><article class="admin-panel"><h2><?=$editing?'Modifier le service':'Ajouter un service'?></h2><form method="post" class="admin-form"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$editing['id']??0?>"><label>Nom du service<input name="nom" maxlength="100" required value="<?=e((string)($editing['nom']??''))?>"></label><button class="admin-button admin-primary">Enregistrer</button><?php if($editing):?><a href="services.php">Annuler</a><?php endif;?></form></article><article class="admin-panel"><div class="panel-heading"><h2>Services enregistrés (<?=count($services)?>)</h2></div><form method="get" class="service-search"><input type="search" name="q" value="<?=e($search)?>" placeholder="Rechercher"><button class="admin-button admin-secondary">Chercher</button></form><div class="table-wrap"><table class="admin-table"><thead><tr><th>Service</th><th>Laboratoires associés</th><th></th></tr></thead><tbody><?php foreach($services as $item):?><tr><td><?=e($item['nom'])?></td><td><?=$item['lab_count']?></td><td><a href="services.php?id=<?=$item['id']?>">Modifier</a><form method="post" data-confirm="Supprimer ce service et ses associations ?" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$item['id']?>"><button class="danger-link">Supprimer</button></form></td></tr><?php endforeach;?><?php if(!$services):?><tr><td colspan="3" class="empty-cell">Aucun service trouvé.</td></tr><?php endif;?></tbody></table></div></article></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
